import { MySharedComponentModule } from 'src/app/shared/my-shared-component.module';

@NgModule({
  imports: [BrowserModule, MySharedComponentModule],
  declarations: [AppComponent],
  bootstrap: [AppComponent]
})
export class AppModule {}
```

6. In the component where you want to use the shared component, inject the component and use it as a directive:
```typescript
